(1418, 25, 7, 21, '', '', '2026-08-26 10:37:56', '2026-08-26 10:37:56'),
(1419, 25, 7, 23, 'belum membuat laporan tindak lanjut utk jurusan', 'melengkapi laporan tindak lanjut utk jurusan', '2026-08-26 10:41:10', '2026-08-26 10:41:10'),
(1420, 25, 7, 18, 'belum analsis dampak', 'perlu dilakukan analisis dampak', '2026-08-26 10:32:58', '2026-08-26 10:32:58'),
