INSERT INTO `kriteria` (`id`, `name`, `deskripsi`, `created_at`, `updated_at`) VALUES
(1, 'Visi Keilmuan Program Studi', 'Menjelaskan arah, fokus keilmuan, serta pencapaian visi program studi dalam menghasilkan lulusan yang sesuai perkembangan ilmu dan kebutuhan masyarakat.', NULL, NULL),
(2, 'Tata Pamong dan Tata Kelola UPPS', 'Mengatur sistem kepemimpinan, pengelolaan organisasi, serta tata kelola penyelenggaraan pendidikan yang transparan dan akuntabel di lingkungan UPPS.', NULL, NULL),
(3, 'Mahasiswa', 'Mencakup kualitas penerimaan, layanan, pengembangan prestasi, dan keberhasilan studi mahasiswa dalam program pendidikan.', NULL, NULL),
(4, 'Dosen dan Tenaga Kependidikan', 'Menguraikan kualifikasi, kompetensi, beban kerja, dan pengembangan profesional dosen serta tenaga kependidikan.', NULL, NULL),
(5, 'Keuangan, Sarana, dan Prasarana Pendidikan', 'Menjelaskan kecukupan dan pengelolaan dana, fasilitas, serta lingkungan belajar yang menunjang proses pendidikan.', NULL, NULL),
(6, 'Pendidikan', 'Menguraikan proses pembelajaran, kurikulum, metode, serta capaian pembelajaran lulusan yang diterapkan program studi.', NULL, NULL),
(7, 'Penelitian', 'Mencakup aktivitas penelitian, produktivitas, relevansi, dan kontribusi penelitian terhadap pengembangan ilmu dan masyarakat.', NULL, NULL),
(8, 'Pengabdian Kepada Masyarakat', 'Menggambarkan kegiatan pengabdian yang dilakukan dosen dan mahasiswa serta dampaknya bagi masyarakat.', NULL, NULL),
(9, 'Penjaminan Mutu', 'Menjelaskan sistem penjaminan mutu internal meliputi perencanaan, pelaksanaan, evaluasi, dan peningkatan berkelanjutan.', NULL, NULL);
