INSERT INTO `syarat_unggul` (`id`, `nomor`, `matriks_id`, `elemen`, `indikator`, `syarat_tahun`, `created_at`, `updated_at`) VALUES
(1, 1, 18, 'Kualitas DTPS (Elemen 19 di Buku 4)', 'Pada saat TS, Dosen Tetap Program Studi (DTPS) memiliki kualifikasi akademik doktor dan jabatan akademik tertentu.', '{\"3_tahun\":\"a. \\u2265 1 DTPS memiliki kualifikasi akademik doktor. b. \\u2265 2 DTPS memiliki jabatan akademik minimal lektor\",\"5_tahun\":\"a. \\u2265 2 DTPS memiliki kualifikasi akademik doktor. b. \\u2265 2 DTPS memiliki jabatan akademik minimal lektor dan \\u2265 1 DTPS memiliki jabatan akademik minimal lektor kepala.\"}', NULL, NULL),
(2, 2, 48, 'Kurikulum (Elemen 49 di Buku 4)', 'Program Studi (PS) melakukan asesmen pencapaian Capaian Pembelajaran Lulusan (CPL) berdasarkan capaian hasil belajar mahasiswa pada mata kuliah penciri keilmuan PS, melakukan evaluasi terhadap hasil asesmen pencapaian CPL, dan melakukan tindak lanjut hasil evaluasi terhadap hasil asesmen pencapaian CPL.', '{\"3_tahun\":\"Skor \\u2265 3.0\",\"5_tahun\":\"Skor \\u2265 3.5\"}', NULL, NULL),
(3, 3, 34, 'Pembelajaran Mikro (microteaching) atau nama lain yang sejenis (Elemen 35 di Buku 4)', 'PS melaksanakan microteaching atau nama lain yang sejenis bagi PS kependidikan nonmengajar sebagai tahapan pengembangan kompetensi mengajar atau kompetensi lain yang sejenis bagi PS kependidikan nonmengajar.', '{\"3_tahun\":\"Skor \\u2265 3.0\",\"5_tahun\":\"Skor \\u2265 3.5\"}', NULL, NULL),
(4, 4, 63, 'Pelaksanaan SPMI dengan siklus PPEPP standar pendidikan tinggi (Elemen 64 di Buku 4)', 'PT/UPPS/PS melaksanakan Sistem Penjaminan Mutu Internal (SPMI) dengan siklus Penetapan, Pelaksanaan, Evaluasi, Pengendalian, dan Peningkatan (PPEPP) standar pendidikan tinggi.', '{\"3_tahun\":\"Skor \\u2265 3.0\",\"5_tahun\":\"Skor \\u2265 3.5\"}', NULL, NULL),
(5, 5, 14, 'Produktivitas Karya Inovatif dan Karya Ilmiah Mahasiswa (Elemen 15 di Buku 4)', 'Dalam 5 tahun terakhir, mahasiswa dalam jumlah tertentu menghasilkan karya inovatif, publikasi ilmiah yang sesuai dengan bidang keilmuan PS, dan/atau karya seni yang dipamerkan/ dipagelarkan.', '{\"3_tahun\":\"\\u2265 15% mahasiswa memiliki karya inovatif yang dapat berbentuk book chapter atau buku berISBN, paten\\/paten sederhana, karya ilmiah yang dipublikasikan pada jurnal nasional terakreditasi minimal Sinta 5 sesuai dengan bidang keilmuannya, dan\\/atau karya seni yang dipamerkan\\/ dipagelarkan.\",\"5_tahun\":\"\\u2265 25% mahasiswa memiliki karya inovatif yang dapat berbentuk book chapter atau buku berISBN, paten\\/paten sederhana, karya ilmiah yang dipublikasikan pada jurnal nasional terakreditasi minimal Sinta 4 sesuai dengan bidang keilmuannya, dan\\/atau karya seni yang dipamerkan\\/ dipagelarkan.\"}', NULL, NULL),
(6, 6, 55, 'Produktivitas Publikasi DTPS (Elemen 56 di Buku 4)', 'Dalam 3 tahun terakhir, DTPS memiliki publikasi di jurnal nasional dan/atau jurnal internasional sebagai penulis pertama atau corresponding author.', '{\"3_tahun\":\"\\u2265 20% DTPS memiliki publikasi pada jurnal nasional minimal Sinta 4 dan\\/atau jurnal internasional sebagai penulis pertama atau corresponding author.\",\"5_tahun\":\"\\u2265 20% DTPS memiliki publikasi pada jurnal nasional minimal Sinta 4 dan\\/atau jurnal internasional sebagai penulis pertama atau corresponding author.\"}', NULL, NULL);
